E
cd resources
cat > Author.json <<'E'
{"name":"Author","path":"/authors","table":"author","itemsPerPage":2,
"properties":{"id":{"type":"integer","identifier":true,"readOnly":true},"name":{"type":"string"}}}
E
cat > Book.json <<'E'
{"name":"Book","path":"/books","query":"book.query.ts","command":"book.command.ts","itemsPerPage":2,
"input":{"title":{"type":"string","required":true},"author_id":{"type":"integer","required":true},"published":{"type":"boolean"}},
"properties":{"id":{"type":"integer","identifier":true},"title":{"type":"string"},"author":{"type":"string","filterable":true},"published":{"type":"boolean"}}}
E
cat > book.query.ts <<'E'
export default function query(ctx) {
  return ctx.sql`SELECT b.id, b.title, a.name AS author, b.published FROM book b JOIN author a ON a.id = b.author_id WHERE b.published`;
}
E
cat > book.command.ts <<'E'
function check(authorId, published, ctx) {
  if (!published) return;
  const [a] = ctx.db.query(ctx.sql`SELECT name FROM author WHERE id = ${authorId}`);
  if (a && (a.name === null || a.name === "")) {
    ctx.reject({ message: "a book whose author has no name cannot be published", pointer: "/published", status: 422 });
  }
}
export function create(input, ctx) {
  const published = input.published === true;
  check(input.author_id, published, ctx);
  const [row] = ctx.db.query(ctx.sql`INSERT INTO book (title, author_id, published) VALUES (${input.title}, ${input.author_id}, ${published}) RETURNING id`);
  return row.id;
}
export function update(input, ctx) {
  const [cur] = ctx.db.query(ctx.sql`SELECT author_id, published FROM book WHERE id = ${ctx.id}`);
  const authorId = "author_id" in input ? input.author_id : cur.author_id;
  const published = "published" in input ? input.published === true : cur.published;
  check(authorId, published, ctx);
  if ("title" in input) ctx.db.exec(ctx.sql`UPDATE book SET title = ${input.title} WHERE id = ${ctx.id}`);
  if ("author_id" in input) ctx.db.exec(ctx.sql`UPDATE book SET author_id = ${input.author_id} WHERE id = ${ctx.id}`);
  if ("published" in input) ctx.db.exec(ctx.sql`UPDATE book SET published = ${published} WHERE id = ${ctx.id}`);
}
export function remove(input, ctx) {
  ctx.db.exec(ctx.sql`DELETE FROM book WHERE id = ${ctx.id}`);
}
E
cat > Export.json <<'E'
{"name":"AuthorReport","operations":[{"method":"GET","path":"/business/export","format":"csv","query":"report.query.ts"}],
"properties":{"author":{"type":"string"},"published_books":{"type":"integer"}}}
E
cat > report.query.ts <<'E'
export default function query(ctx) {
  return ctx.sql`SELECT a.name AS author, count(b.id)::int AS published_books FROM author a LEFT JOIN book b ON b.author_id = a.id AND b.published WHERE a.name IS NOT NULL AND a.name <> '' GROUP BY a.id, a.name ORDER BY a.name, a.id`;
}
E

cd /work/resources
cat > Quote.json <<'E'
{"name":"Quote","path":"/quotes","query":"quote.query.ts","itemsPerPage":2,"readOnly":true,
"allow":{"fetch":["127.0.0.1:18090"]},
"properties":{"id":{"type":"integer","identifier":true},"text":{"type":"string"},"author":{"type":"string","filterable":true}}}
E
cat > quote.query.ts <<'E'
export default async function query(ctx) {
  const res = await ctx.fetch("http://127.0.0.1:18090/quotes.json");
  let rows = (await res.json()).map((q) => ({ id: q.id, text: q.quote, author: q.by }));
  if (ctx.operation === "item") return rows.find((r) => r.id === ctx.id) ?? null;
  if (ctx.filters.author !== undefined) rows = rows.filter((r) => r.author === ctx.filters.author);
  rows.sort((a, b) => a.id - b.id);
  const start = (ctx.page - 1) * ctx.itemsPerPage;
  return { items: rows.slice(start, start + ctx.itemsPerPage), totalItems: rows.length };
}
E
cd /work; (./caddy run > caddy.log 2>&1 &); sleep 4
curl -s localhost:8089/quotes?author=Frank%20Herbert | head -c 400; echo
curl -s localhost:8089/business/export; curl -s localhost:8089/books | head -c 500; echo
curl -s -XPOST localhost:8089/authors -H 'Content-Type: application/json' -d '{}'
echo; curl -s "localhost:8089/authors?page=1" | head -c 300

